def setup_payment_listeners():
    @event.listens_for(Session, "after_commit")
    def after_commit(session):
        for obj in session.new:
            if isinstance(obj, Payment):
                sync_service.sync_payment(obj, event_type='created')
                user = User.query.get(obj.user_id)
                if user:
                    content = f"User {user.username} created payment {obj.payment_id}: {float(obj.amount):.2f} {obj.currency} to {obj.recipient_name or 'N/A'}, method: {obj.payment_method}, status: {obj.status}, created: {obj.created_at.isoformat()}"
                    supermemory_client.add_memory(
