@app.route('/pay/<link_id>', methods=['GET', 'POST'])
def pay_link(link_id):
    link = PaymentLink.query.filter_by(link_id=link_id).first()
    if not link or not link.is_active or link.current_uses >= link.max_uses or link.expires_at < datetime.utcnow():
        return jsonify({
            'success': False,
            'error': 'Invalid or expired link'
        }), 400
    if request.method == 'GET':
        return jsonify({
            'amount': str(link.amount),
            'currency': link.currency,
            'description': link.description
        })
    data = request.get_json()
    result = payment_processor.process_payment(link.user_id, {**data, 'amount': link.amount, 'currency': link.currency, 'description': link.description})
    if result['success']:
        link.current_uses += 1
        if link.current_uses >= link.max_uses:
            link.is_active = False
            link.used_at = datetime.utcnow()
        db.session.commit()
    return jsonify(result)

