@app.route('/auth/callback')
@login_required
def auth_callback():
    try:
        code = request.args.get('code')
        state = request.args.get('state')
        error = request.args.get('error')
        if error:
            flash(f'Hitelesítési hiba: {error}', 'error')
            return redirect(url_for('index'))
        if not code or not state:
            flash('Hiányzó hitelesítési paraméterek', 'error')
            return redirect(url_for('index'))
        if state != current_user.consent_id:
            flash('Érvénytelen állapot', 'error')
            return redirect(url_for('index'))
        token_data = erste_client.exchange_code_for_token(code, state)
        current_user.access_token = token_data.get('access_token')
        current_user.refresh_token = token_data.get('refresh_token')
        current_user.token_expires_at = datetime.utcnow() + timedelta(seconds=token_data.get('expires_in', 3600))
        db.session.commit()
        supermemory_client.add_memory(
            content=f"User {current_user.username} successfully authenticated Erste Bank account at {datetime.utcnow().isoformat()}",
            container_tags=[f"user:{current_user.id}", "erste", "auth"],
            metadata={
                "user_id": str(current_user.id),
                "event_type": "erste_auth_success",
                "timestamp": datetime.utcnow().isoformat()
            }
        )
        accounts_data = erste_client.get_accounts(current_user.access_token)
        for account_data in accounts_data.get('accounts', []):
            account = Account.query.filter_by(user_id=current_user.id, account_id=account_data.get('resourceId')).first()
            if not account:
                account = Account(
                    user_id=current_user.id,
                    account_id=account_data.get('resourceId'),
                    iban=account_data.get('iban'),
                    name=account_data.get('name'),
                    currency=account_data.get('currency', 'HUF'),
                    account_type=account_data.get('cashAccountType')
                )
                db.session.add(account)
                db.session.commit()
            balances = erste_client.get_account_balances(current_user.access_token, account.account_id)
            if balances.get('balances'):
                account.balance = Decimal(balances['balances'][0]['amount']['amount'])
                if len(balances['balances']) > 1:
                    account.available_balance = Decimal(balances['balances'][1]['amount']['amount'])
                else:
                    account.available_balance = account.balance
                account.last_updated = datetime.utcnow()
                db.session.commit()
            supermemory_client.add_memory(
                content=f"User {current_user.username} Erste account {account.iban or account.account_id}, name: {account.name}, type: {account.account_type}, balance: {float(account.balance):.2f} {account.currency}, available: {float(account.available_balance):.2f} {account.currency}, updated: {account.last_updated.isoformat()}",
                container_tags=[f"user:{current_user.id}", "accounts", "erste"],
                metadata={
                    "user_id": str(current_user.id),
                    "account_id": account.account_id,
                    "iban": account.iban or "",
                    "currency": account.currency,
                    "balance": str(account.balance),
                    "account_type": account.account_type or "",
                    "event_type": "account_imported",
                    "timestamp": datetime.utcnow().isoformat()
                }
            )
        flash('Sikeres Erste Bank hitelesítés!', 'success')
        return redirect(url_for('index'))
    except Exception as e:
        logger.error(f"Error in auth callback: {e}")
        flash('Hiba a hitelesítés során', 'error')
        return redirect(url_for('index'))

